    CREATE INDEX IDX_tibco_stubs_user_id
        ON dbo.tibco_stubs (JSON_VALUE(stub_data, '$.userId'));

    -- Destination type (queue/topic) + name drive message routing
    CREATE INDEX IDX_tibco_stubs_destination
        ON dbo.tibco_stubs (
            JSON_VALUE(stub_data, '$.destinationType'),
            JSON_VALUE(stub_data, '$.destinationName')
        );

    PRINT 'Created table: tibco_stubs';
END
ELSE
    PRINT 'Table already exists, skipping: tibco_stubs';
GO

